"""Switch Фм-1 to Ø28 (user 06.11: «арматураларын максималды, 28 қылып»), beam 4+4 with 2 hoops."""


def rep(p, R):
    s = open(p, encoding='utf-8').read()
    for a, b in R:
        if s.count(a) == 0:
            print('MISS', p, a[:70]); continue
        s = s.replace(a, b)
    open(p, 'w', encoding='utf-8').write(s)


